+
+// Codes compartidos por ambos caminos. Se conserva el prefijo SYLLABUS_OFFERING_* por
+// compatibilidad con los consumidores actuales de createSyllabusOffering: el camino generico debe
+// rechazar con el MISMO error/codigo que la mutation propia (TC-REQ-02-1 / TC-REQ-02-5).
+export const OFFERING_ERR = Object.freeze({
+  ACTIVITY_NOT_FOUND: 'SYLLABUS_OFFERING_ACTIVITY_NOT_FOUND',
+  ACTIVITY_NOT_COURSE: 'SYLLABUS_OFFERING_ACTIVITY_NOT_COURSE',
+  CODE_DUPLICATE: 'SYLLABUS_OFFERING_CODE_DUPLICATE',
+});
+
+const COURSE_RECORD_TYPE = 'Course';
+
+/**
+ * Verifica que `activityId` apunte a una Activity existente y recordType=Course. Los mensajes son
+ * IDENTICOS en ambos caminos (TC-REQ-02-1). Retorna la Activity (id, recordType, code,
