+ * @param {object} args
+ * @param {object} args.prisma
+ * @param {string} args.activityId
+ * @returns {Promise<{id:string, recordType:string, code:string|null, executionUnitId:string|null}>}"},{"file":"mods/curriculum-design/logic/syllabus-offering.resolver.js","added":13,"removed":10,"patch":"-const ERR = {
