-};
+// TICKET-148 REQ-02: los dos checks del sílabo (Activity=Course + code único scoped) se extrajeron
+// a un helper puro compartido con el camino generico (validateSectionCreate). Los codes de esos dos
+// checks viven ahora en OFFERING_ERR (fuente unica); aca quedan solo los codes propios de esta
+// mutation (sesion, campos requeridos, resolucion de OrgUnit).
+import { assertActivityIsCourse, assertOfferingCodeUnique, OFFERING_ERR } from './helpers/offeringGuard.js';
+
