+  NAME_REQUIRED: 'SYLLABUS_OFFERING_NAME_REQUIRED',
+  CODE_REQUIRED: 'SYLLABUS_OFFERING_CODE_REQUIRED',
+  ACTIVITY_REQUIRED: 'SYLLABUS_OFFERING_ACTIVITY_REQUIRED',
+  NO_ORG_UNIT: 'SYLLABUS_OFFERING_NO_ORG_UNIT',
+};"},{"file":"mods/curriculum-design/logic/syllabus-offering.resolver.js","added":17,"removed":26,"patch":"-  const activity = await prisma.Activity.findUnique({
