+        code,
+        duplicateMessage:"},{"file":"mods/curriculum-design/tests/unit/activityCreateDraftGuard.test.js","added":88,"removed":0,"patch":"+/**
+ * activityCreateDraftGuard.test.js — TICKET-148 S1.T2 / REQ-01 (hueco 1).
+ *
+ * Un create generico de Activity (createInstance / up1_create_object / API) no puede producir una
+ * Activity PUBLICADA sin pasar por el gate I1: validateSectionCreate fuerza status='Draft' en el
+ * payload de create. Publicar queda como transicion exclusiva de updateInstance, donde
+ * assertActivityEvaluationsOnPublish (intacto) sigue validando el arbol de evaluacion.
+ *
+ * Cobertura declarada:
+ *   - TICKET-148-TC-REQ-01-1 [error]  : status:'Active' → forzado a 'Draft' (no se publica).
+ *   - TICKET-148-TC-REQ-01-2 [happy]  : status:'Draft' explicito → sigue en Draft.
+ *   - TICKET-148-TC-REQ-01-3 [edge]   : sin campo status → nace Draft (default preservado).
+ *   - TICKET-148-TC-REQ-01-4 [regression]: el guard de publish del update no se altero.
+ */
+import { describe, it, expect } from 'vitest';
+import { validateSectionCreate } from '../../logic/sectionValidation.resolver.js';
+import { _internals as updateInternals } from '../../logic/polymorphicUpdate.resolver.js';
+
+const EVAL = 'rt__EvaluationComponent__curricularsection';
+
+// prisma con un arbol de evaluacion configurable para el guard de publish (mismo shape que
+// activityEvaluations.test.js): nf=100 y sus hijos suman `childSum`.
+function makeEvalPrisma(childSum) {
+  return {
+    [EVAL]: {
+      findMany: async () => [
+        { curricularsectionId: 'nf', weight: 100, curricularsection: { parentId: null } },
+        { curricularsectionId: 'q1', weight: childSum, curricularsection: { parentId: 'nf' } },
+      ],
+    },
+  };
+}
+
+describe('validateSectionCreate — Activity create fuerza Draft (REQ-01)', () => {
+  it('TC-REQ-01-1: create con status:"Active" queda forzado a "Draft" sin lanzar', async () => {
+    const data = { name: 'Cálculo I', status: 'Active' };
+    await expect(
+      validateSectionCreate({ objectType: 'Activity', data, context: { prisma: {} } }),
+    ).resolves.toBeUndefined();
+    expect(data.status).toBe('Draft'); // no se publica por el create generico"},{"file":"mods/curriculum-design/tests/unit/offeringGenericGuard.test.js","added":122,"removed":0,"patch":"+/**
+ * offeringGenericGuard.test.js — TICKET-148 S1.T2 / REQ-02 (hueco 2).
+ *
+ * Un create generico de un Offering recordType='Syllabus' (createInstance / up1_create_object / API)
+ * debe pasar por las MISMAS dos reglas del sílabo que createSyllabusOffering, hoy enforzadas solo en
+ * esa mutation propia. La regla vive en UN helper compartido (offeringGuard) y se engancha al camino
+ * generico en validateSectionCreate, scoped a recordType='Syllabus' para NO tocar los ServiceOffer
+ * de engagement.
+ *
+ * Cobertura declarada:
+ *   - TICKET-148-TC-REQ-02-1 [error]   : activityId → Activity Service: rechazado (mismo codigo que
+ *     createSyllabusOffering).
+ *   - TICKET-148-TC-REQ-02-2 [error]   : code duplicado en el mismo (activityLineId, termId):
+ *     rechazado con mensaje terminado en el formato Prisma de unicidad (RULE-curriculum-design-005).
+ *   - TICKET-148-TC-REQ-02-3 [happy]   : Course + code libre: pasa (no lanza), ambos checks corren.
+ *   - TICKET-148-TC-REQ-02-4 [boundary]: code existente en OTRO termId: aceptado (unicidad scoped).
+ */
+import { describe, it, expect, vi } from 'vitest';
+import { validateSectionCreate } from '../../logic/sectionValidation.resolver.js';
+
+const COURSE = { id: 'act-course', recordType: 'Course', code: 'MAT101', executionUnitId: 'org-1' };
+const SERVICE = { id: 'act-service', recordType: 'Service', code: 'SVC1', executionUnitId: 'org-1' };
+
+// prisma mock: Activity.findUnique resuelve por id; Offering.findFirst devuelve `duplicate`.
+function makePrisma({ duplicate = null } = {}) {
+  return {
+    Activity: {
+      findUnique: vi.fn(async ({ where }) =>
+        where.id === 'act-course' ? COURSE : where.id === 'act-service' ? SERVICE : null,
+      ),
+    },
+    Offering: {
+      findFirst: vi.fn(async () => duplicate),
+    },
+  };
+}
+
+function syllabusData(overrides = {}) {
+  return {
+    recordType: 'Syllabus',"}],"tests":[{"name":"cd /Users/edobacon/Workspace/uplanner/up1/mods/curriculum-design; npx vitest run","status":"pass"},{"name":"cd /Users/edobacon/Workspace/uplanner/up1/mods/curriculum-design; npx vitest run","status":"pass"},{"name":"cd /Users/edobacon/Workspace/uplanner/up1/mods/curriculum-design; npx vitest run","status":"pass"}],"result":{"summary":"- Ejecuté S1.T2 cubriendo REQ-01 (hueco 1: Activity) y REQ-02 (hueco 2: Offering), tal como los describe el Objetivo, la lista de casos de test y los criterios de aceptación de la invocación (el plan angosto de S1.T2 lista solo REQ-01, pero el objetivo y los TC asignados incluyen ambos; ambos caen dentro del scope declarado y del límite de 50 archivos).
- REQ-01: en validateSectionCreate (sectionValidation.resolver.js) agregué el dispatch objectType==='Activity' que fuerza data.status='Draft' in-place en el create (también en data.extended.status si viene ahí). Publicar queda como transición exclusiva de updateInstance, donde assertActivityEvaluationsOnPublish sigue intacto. 'Draft' es el static_default del schema, así que no inyecta valor inválido ni rompe el create legítimo en Draft.
- REQ-02: extraje los dos checks del sílabo a un helper puro compartido nuevo (logic/helpers/offeringGuard.js): assertActivityIsCourse (Activity debe ser recordType='Course', retorna la fila para reuso) y assertOfferingCodeUnique (code único scoped por (activityLineId, termId)). Lo consume createSyllabusOffering (preservando sus mensajes/códigos EXACTOS, TC-REQ-02-5) y el nuevo dispatch objectType==='Offering' en validateSectionCreate.
- El dispatch genérico está SCOPED a recordType==='Syllabus': impacto colateral clave — validateSectionCreate es el override singleton de createInstance y corre para TODO Offering; sin el scope, el check de Course rechazaría los ServiceOffer de engagement. createServiceOffering (engagement) es mutation propia y no pasa por el override, pero un create genérico de ServiceOffer sí; el scope lo protege (cubierto por test dedicado).
